"""Utilities for computing rolling statistics over numeric sensor readings."""

from typing import Iterator, List, Sequence


def rolling_windows(values: Sequence[float], window_size: int) -> Iterator[List[float]]:
    """
    Yield every contiguous window of length window_size found in values,
    sliding one position at a time from the start of the sequence to the end.
    """
    if window_size <= 0:
        raise ValueError("window_size must be positive")
    if window_size > len(values):
        return
    for start in range(len(values) - window_size + 1):
        yield list(values[start:start + window_size])


def rolling_average(values: Sequence[float], window_size: int) -> List[float]:
    """Return the average of each window produced by rolling_windows."""
    return [sum(window) / len(window) for window in rolling_windows(values, window_size)]
